import java.util.Scanner; public class Solution { public static void main(String[] args) { Scanner sc = new Scanner(System.in); if (!sc.hasNextInt()) return; int n = sc.nextInt(); int[] scores = new int[n]; for (int i = 0; i < n; i++) { scores[i] = sc.nextInt(); } int[] result = breakingRecords(scores); System.out.println(result[0] + " " + result[1]); } public static int[] breakingRecords(int[] scores) { int min = scores[0]; int max = scores[0]; int minCount = 0; int maxCount = 0; for (int i = 1; i < scores.length; i++) { if (scores[i] > max) { max = scores[i]; maxCount++; } else if (scores[i] < min) { min = scores[i]; minCount++; } } return new int[]{maxCount, minCount}; } }